package io.knowledgebrain.content;
import java.util.*;import org.springframework.mock.web.MockHttpServletRequest;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class ActivityExportIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;RecordConceptStore store;BookmarkStore bookmarks;QuestionStore questions;DecisionStore decisions;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="e".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));ds.setUser("brain_content");ds.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));schema="record_concepts_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new RecordConceptStore(ds,Clock.systemUTC());bookmarks=new BookmarkStore(ds,Clock.systemUTC());questions=new QuestionStore(ds,Clock.systemUTC());decisions=new DecisionStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 UUID create(RecordConceptStore.Kind k){return switch(k){case BOOKMARK->bookmarks.create(space,actor,key(),new BookmarkStore.Input("Saved bookmark","https://example.test/","Memo"),trace).bookmark().bookmarkId();case QUESTION->questions.create(space,actor,key(),new QuestionStore.Input("Saved question","Context","","OPEN"),trace).question().questionId();case DECISION->decisions.create(space,actor,key(),new DecisionStore.Input("Saved decision","Context","Choice","Reason","Alternative","DECIDED"),trace).decision().decisionId();};}
 void retire(RecordConceptStore.Kind k,UUID id){switch(k){case BOOKMARK->bookmarks.change(space,id,actor,1,null,true,trace);case QUESTION->questions.change(space,id,actor,1,null,true,trace);case DECISION->decisions.change(space,id,actor,1,null,true,trace);}}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}

 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/internal/content/activity-events");r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 ActivityExportController api(){return new ActivityExportController(ds,"a".repeat(43),new SimpleMeterRegistry());}
 @Test void originalRetainedEventsRecoverFullHistoryWithFixedWatermarkAndOrderedLinks()throws Exception{for(var kind:RecordConceptStore.Kind.values()){var id=create(kind);store.replace(space,kind,id,actor,0,List.of(ids.next(),ids.next()),trace);store.replace(space,kind,id,actor,1,List.of(),trace);retire(kind,id);}var api=api();var first=api.page(null,null,request()).getBody();assertEquals(5,first.items().size());assertNotNull(first.nextAfter());var watermark=first.through();create(RecordConceptStore.Kind.BOOKMARK);var items=new ArrayList<ActivityExportController.Item>();UUID after=null;do{var page=api.page(after,watermark,request()).getBody();assertEquals(watermark,page.through());items.addAll(page.items());after=page.nextAfter();assertTrue(items.size()<20);}while(after!=null);assertEquals(12,items.size());assertEquals(Set.of("content.bookmark.v1","content.question.v1","content.decision.v1","content.record-concepts.v1"),new HashSet<>(items.stream().map(ActivityExportController.Item::topic).toList()));for(var item:items){var stored=sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId());assertArrayEquals(stored,Base64.getDecoder().decode(item.payload()));}assertEquals("no-store",api.page(null,watermark,request()).getHeaders().getCacheControl());}
 @Test void scopedHttpsAuthorityAndStrictBoundedRequestAreRequired(){var api=api();var http=request();http.setSecure(false);var cookie=request();cookie.addHeader("Cookie","__Host-brain_guest="+"b".repeat(43));var wrong=request();wrong.removeHeader("Authorization");wrong.addHeader("Authorization","Bearer "+"b".repeat(43));for(var r:List.of(http,cookie,wrong))status(401,()->api.page(null,null,r));var dup=request();dup.addParameter("after","x","y");status(400,()->api.page(null,null,dup));var unknown=request();unknown.addParameter("kind","QUESTION");status(400,()->api.page(null,null,unknown));var body=request();body.setContent("{}".getBytes());status(400,()->api.page(null,null,body));status(400,()->api.page(UUID.randomUUID(),null,request()));}
 @Test void noteAndDailyRecoveryReturnsAllOriginalVersionsIncludingRetirementAndNoOpReopen()throws Exception{var notes=new NoteStore(ds,Clock.systemUTC());var ordinary=notes.create(space,actor,"Original note","Historical body",trace);notes.change(space,ordinary.noteId(),actor,1,"Changed note","Current body",false,trace);notes.change(space,ordinary.noteId(),actor,2,null,null,true,trace);var daily=notes.openDaily(space,"1582-10-10","Asia/Seoul",actor,trace);notes.openDaily(space,"1582-10-10","Asia/Seoul",actor,trace);notes.change(space,daily.entry().note().noteId(),actor,1,"Daily edit","Draft",false,trace);notes.change(space,daily.entry().note().noteId(),actor,2,null,null,true,trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null,through=null;do{var page=api().page(after,through,request()).getBody();through=page.through();rows.addAll(page.items());after=page.nextAfter();}while(after!=null);assertEquals(17,rows.size());assertEquals(6,rows.stream().filter(i->i.topic().equals("content.note.v1")).count());assertEquals(3,rows.stream().filter(i->i.topic().equals("content.daily-note.v1")).count());for(var item:rows){assertArrayEquals(sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId()),Base64.getDecoder().decode(item.payload()));}assertEquals(3,notes.history(space,ordinary.noteId(),Long.MAX_VALUE,10).size());}

 @Test void originalNoteConceptEventsRetainIndependentRevisionsOrderEmptyAndArchivedSnapshots()throws Exception{var notes=new NoteStore(ds,Clock.systemUTC());var n=notes.create(space,actor,"Canonical Note title","Unchanged body",trace);var a=ids.next();var b=ids.next();var first=notes.concepts(space,n.noteId(),actor,0,List.of(a,b),trace);var reordered=notes.concepts(space,n.noteId(),actor,1,List.of(b,a),trace);assertEquals(first.items().getFirst(),reordered.items().getLast());notes.concepts(space,n.noteId(),actor,2,List.of(),trace);notes.concepts(space,n.noteId(),actor,3,List.of(a),trace);notes.change(space,n.noteId(),actor,1,null,null,true,trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null,through=null;do{var page=api().page(after,through,request()).getBody();through=page.through();rows.addAll(page.items());after=page.nextAfter();}while(after!=null);assertEquals(10,rows.size());var links=rows.stream().filter(i->i.topic().equals("content.note-concepts.v1")).toList();assertEquals(5,links.size());var audit=notes.conceptHistory(space,n.noteId(),Long.MAX_VALUE,10);for(var item:links){var raw=Base64.getDecoder().decode(item.payload());assertArrayEquals(sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId()),raw);var env=io.knowledgebrain.contracts.content.concepts.v1.ConceptEventEnvelopeV1.parseFrom(raw);var p=io.knowledgebrain.contracts.content.concepts.v1.NoteConceptsChangedPayloadV1.parseFrom(env.getPayload());var revision=audit.stream().filter(v->v.conceptVersion()==p.getConceptVersion()).findFirst().orElseThrow();assertEquals(revision.revisionId().toString(),p.getRevisionId());assertEquals(revision.snapshot().items().stream().map(v->v.conceptId().toString()).toList(),p.getLinksList().stream().map(io.knowledgebrain.contracts.content.concepts.v1.NoteConceptLinkV1::getConceptId).toList());if(p.getConceptVersion()==5){assertEquals("RETIRED",p.getNoteState());assertEquals(0,p.getLinksCount());assertEquals(2,p.getNoteVersion());}else assertEquals(1,p.getNoteVersion());}assertEquals(2,notes.history(space,n.noteId(),Long.MAX_VALUE,10).size());}
 @Test void retainedMetadataExportPreservesOriginalTypedJsonAndRetiredAssignments()throws Exception{var notes=new NoteStore(ds,Clock.systemUTC());var n=notes.create(space,actor,"Metadata source","Canonical body",trace);String decimal="12345678901234567890.123456789012345678",expanded="12345678901234567890123456789012345678"+"0".repeat(18);var edit=MetadataInput.parse(("{\"tags\":[\"study\"],\"properties\":{\"precise\":{\"type\":\"NUMBER\",\"value\":"+decimal+"},\"expanded\":{\"type\":\"NUMBER\",\"value\":12345678901234567890123456789012345678e18},\"day\":{\"type\":\"DATE\",\"value\":\"0000-02-29\"},\"done\":{\"type\":\"BOOLEAN\",\"value\":true}}}").getBytes(java.nio.charset.StandardCharsets.UTF_8));var first=notes.metadata(space,n.noteId(),actor,0,edit,trace);notes.change(space,n.noteId(),actor,1,"Changed body title","Changed body",false,trace);assertEquals(first,notes.metadata(space,n.noteId()));notes.metadata(space,n.noteId(),actor,1,new MetadataInput.Edit(List.of(),List.of()),trace);var restored=notes.metadata(space,n.noteId(),actor,2,edit,trace);assertEquals(first.tags(),restored.tags());notes.change(space,n.noteId(),actor,2,null,null,true,trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null,through=null;do{var page=api().page(after,through,request()).getBody();through=page.through();rows.addAll(page.items());after=page.nextAfter();}while(after!=null);var items=rows.stream().filter(i->i.topic().equals("content.note-metadata.v1")).toList();assertEquals(4,items.size());var audit=notes.metadataHistory(space,n.noteId(),Long.MAX_VALUE,10);for(var item:items){var raw=Base64.getDecoder().decode(item.payload());assertArrayEquals(sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId()),raw);var env=io.knowledgebrain.contracts.content.metadata.v1.MetadataEventEnvelopeV1.parseFrom(raw);var p=io.knowledgebrain.contracts.content.metadata.v1.NoteMetadataChangedPayloadV1.parseFrom(env.getPayload());var revision=audit.stream().filter(v->v.metadataVersion()==p.getMetadataVersion()).findFirst().orElseThrow();assertEquals(revision.revisionId().toString(),p.getRevisionId());if(p.getMetadataVersion()==2){assertEquals(0,p.getTagsCount());assertEquals(0,p.getPropertiesCount());}else{assertEquals(1,p.getTagsCount());assertTrue(p.getPropertiesList().stream().anyMatch(f->f.getName().equals("precise")&&f.getJsonValue().equals(decimal)));assertTrue(p.getPropertiesList().stream().anyMatch(f->f.getName().equals("expanded")&&f.getJsonValue().equals(expanded)));}if(p.getMetadataVersion()==4){assertEquals("RETIRED",p.getNoteState());assertEquals(3,p.getNoteVersion());}}assertEquals(3,notes.history(space,n.noteId(),Long.MAX_VALUE,10).size());}
 @Test void originalWikiLinkRecoveryIncludesReconciliationWithoutBodyEditsStableIdsAndRetirement()throws Exception{var notes=new NoteStore(ds,Clock.systemUTC());var source=notes.create(space,actor,"Source","😀 [[Future#section|shown]] [[Future]]",trace);var before=notes.get(space,source.noteId());var target=notes.create(space,actor,"Future","",trace);assertEquals(before,notes.get(space,source.noteId()));var links=notes.outgoing(space,source.noteId(),null,100);assertEquals(2,links.linkVersion());assertEquals(1,links.noteVersion());assertEquals(List.of("RESOLVED","RESOLVED"),links.items().stream().map(NoteLinkStore.View::status).toList());assertEquals(3,links.items().getFirst().startOffset());notes.change(space,target.noteId(),actor,1,"Renamed","",false,trace);notes.change(space,target.noteId(),actor,2,null,null,true,trace);notes.change(space,source.noteId(),actor,1,null,null,true,trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null,through=null;do{var page=api().page(after,through,request()).getBody();through=page.through();rows.addAll(page.items());after=page.nextAfter();}while(after!=null);var items=rows.stream().filter(i->i.topic().equals("content.note-links.v1")).toList();assertEquals(7,items.size());var sourceRows=new ArrayList<io.knowledgebrain.contracts.content.links.v1.NoteLinksChangedPayloadV1>();for(var item:items){var raw=Base64.getDecoder().decode(item.payload());assertArrayEquals(sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId()),raw);var env=io.knowledgebrain.contracts.content.links.v1.LinkEventEnvelopeV1.parseFrom(raw);var p=io.knowledgebrain.contracts.content.links.v1.NoteLinksChangedPayloadV1.parseFrom(env.getPayload());assertArrayEquals(sql.queryForObject("SELECT payload FROM note_link_revision WHERE revision_id=?",byte[].class,UUID.fromString(p.getRevisionId())),p.toByteArray());if(p.getSourceNoteId().equals(source.noteId().toString()))sourceRows.add(p);}assertEquals(4,sourceRows.size());assertEquals(List.of(1L,1L,1L,2L),sourceRows.stream().map(io.knowledgebrain.contracts.content.links.v1.NoteLinksChangedPayloadV1::getNoteVersion).toList());assertEquals(List.of("UNRESOLVED","RESOLVED","TARGET_RETIRED"),sourceRows.subList(0,3).stream().map(v->v.getLinks(0).getStatus()).toList());assertEquals(sourceRows.get(0).getLinks(0).getLinkId(),sourceRows.get(2).getLinks(0).getLinkId());assertEquals(0,sourceRows.get(3).getLinksCount());}
 @Test void originalAttachmentExportRetainsOrderedMetadataIndependentVersionsAndRetiredEmptyAudit()throws Exception{var notes=new NoteStore(ds,Clock.systemUTC());var n=notes.create(space,actor,"Attachment source","Canonical source",trace);var now=Instant.now();var a=new MediaAvailabilityClient.File(ids.next(),space,"AVAILABLE",2,"proof<img onerror=evil>.pdf","application/pdf",42,"a".repeat(64),now,now);var b=new MediaAvailabilityClient.File(ids.next(),space,"AVAILABLE",2,"image😀.png","image/png",17,"b".repeat(64),now,now);var first=notes.attachments(space,n.noteId(),actor,0,List.of(a,b),trace);var second=notes.attachments(space,n.noteId(),actor,1,List.of(b,a),trace);assertEquals(first.items().getFirst(),second.items().getLast());notes.change(space,n.noteId(),actor,1,"Edited title","Edited body",false,trace);assertEquals(second,notes.attachments(space,n.noteId()));notes.attachments(space,n.noteId(),actor,2,List.of(),trace);var readded=notes.attachments(space,n.noteId(),actor,3,List.of(a),trace);assertNotEquals(first.items().getFirst().attachmentId(),readded.items().getFirst().attachmentId());notes.change(space,n.noteId(),actor,2,null,null,true,trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null,through=null;do{var page=api().page(after,through,request()).getBody();through=page.through();rows.addAll(page.items());after=page.nextAfter();}while(after!=null);var items=rows.stream().filter(i->i.topic().equals("content.note-attachments.v1")).toList();assertEquals(5,items.size());var audit=notes.attachmentHistory(space,n.noteId(),Long.MAX_VALUE,10);for(var item:items){var raw=Base64.getDecoder().decode(item.payload());assertArrayEquals(sql.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId()),raw);var env=io.knowledgebrain.contracts.content.attachments.v1.AttachmentEventEnvelopeV1.parseFrom(raw);var p=io.knowledgebrain.contracts.content.attachments.v1.NoteAttachmentsChangedPayloadV1.parseFrom(env.getPayload());var revision=audit.stream().filter(v->v.attachmentVersion()==p.getAttachmentVersion()).findFirst().orElseThrow();assertEquals(revision.revisionId().toString(),p.getRevisionId());assertEquals(revision.snapshot().items().stream().map(v->v.mediaId().toString()).toList(),p.getAttachmentsList().stream().map(io.knowledgebrain.contracts.content.attachments.v1.NoteAttachmentV1::getMediaId).toList());if(p.getAttachmentVersion()==5){assertEquals("RETIRED",p.getNoteState());assertEquals(3,p.getNoteVersion());assertEquals(0,p.getAttachmentsCount());}}assertEquals(3,notes.history(space,n.noteId(),Long.MAX_VALUE,10).size());}
}
